from typing import List

def maxDistance(side: int, points: List[List[int]], k: int) -> int:
    # 預先計算所有點兩兩之間的曼哈頓距離
    n = len(points)
    dist = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            d = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
            dist[i][j] = dist[j][i] = d

    def can_place(idx: int, count: int, current_selection: List[int], min_d: int) -> bool:
        if count == k:
            return True
        # 如果剩餘的點數不足以填滿 k 個，則剪枝
        if count + (n - idx) < k:
            return False

        for i in range(idx, n):
            # 檢查點 i 是否與已選中的點距離都 >= min_d
            possible = True
            for selected_idx in current_selection:
                if dist[i][selected_idx] < min_d:
                    possible = False
                    break

            if possible:
                current_selection.append(i)
                if can_place(i + 1, count + 1, current_selection, min_d):
                    return True
                current_selection.pop()
        return False

    # 二分搜尋答案範圍：曼哈頓距離最小為 0，最大為 side * 2 (對角線)
    low = 0
    high = side * 2
    ans = 0

    while low <= high:
        mid = (low + high) // 2
        # 從每個點開始嘗試，因為 k 很小，這種回溯通常很快
        found = False
        for i in range(n):
            if can_place(i, 1, [i], mid):
                found = True
                break

        if found:
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    return ans
