            d = abs(x1 - x2) + abs(y1 - y2)
            dist_matrix[i][j] = dist_matrix[j][i] = d

    def can_select(min_dist: int) -> bool:
        # Use backtracking to find if k points exist with pairwise distance >= min_dist
        # Since k is small (<= 25), we use a recursive search with pruning.
        selected = []

        def backtrack(idx: int, count: int) -> bool:
            if count == k:
                return True
            if idx == n or (n - idx) < (k - count):
                return False

            # Optimization: Try to pick points that are "further" first? 
            # Actually, standard backtracking with pruning is usually enough for k=25.
            for i in range(idx, n):
                possible = True
                for s_idx in selected:
                    if dist_matrix[i][s_idx] < min_dist:
                        possible = False
                        break
                if possible:
                    selected.append(i)
                    if backtrack(i + 1, count + 1):
                        return True
                    selected.pop()
            return False

        # To improve backtracking speed, we could sort points by some heuristic,
        # but since the order doesn't strictly matter for correctness, we try basic first.
        return backtrack(0, 0)

    # Binary search on the answer
    low = 0
    high = 2 * side
    ans = 0

    # Heuristic: Sort points to potentially speed up backtracking (e.g., by x then y)
    points.sort()
    for i in range(n):
        for j in range(i + 1, n):
            dist_matrix[i][j] = dist_matrix[j][i] = abs(points[i][0] - points[j][0]) + \
                                                           abs(points[i][1] - points[j][1])

    while low <= high:
        mid = (low + high) // 2
        if mid == 0:
            ans = max(ans, 0)
            low = 1
            continue
        if can_select(mid):
            ans = mid
            low = mid + 1
        else:
