由於數量極少（$n, m \le 10$），我們可以使用 **BFS (廣度優先搜尋)** 來計算每一天能達到的最大金額。

```python
from typing import List
from collections import deque

def maxAmount(initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
    # 建立第一天的轉化圖 (Graph)
    adj1 = {}
    for i in range(len(pairs1)):
        u, v = pairs1[i]
        r = rates1[i]
        if u not in adj1: adj1[u] = []
        adj1[u].append((v, r))
        # 因為可以反向轉換，也要加入 1/r 的邊
        if v not in adj1: adj1[v] = []
        adj1[v].append((u, 1.0 / r))

    # 建立第二天的轉化圖
    adj2 = {}
    for i in range(len(pairs2)):
        u, v = pairs2[i]
        r = rates2[i]
        if u not in adj2: adj2[u] = []
        adj2[u].append((v, r))
        if v not in adj2: adj2[v] = []
        adj2[v].append((u, 1.0 / r))

    # 第一天 BFS：找出所有能轉化的幣種及其最大金額
    max_day1 = {initialCurrency: 1.0}
    queue = deque([initialCurrency])
    while queue:
        curr = queue.popleft()
        if curr in adj1:
            for neighbor, rate in adj1[curr]:
                new_amount = max_day1[curr] * rate
                if neighbor not in max_day1 or new_amount > max_day1[neighbor]:
                    max_day1[neighbor] = new_amount
                    queue.append(neighbor)

    # 第二天 BFS：從第一天所有結果出發，繼續轉化
    max_final = {curr: amt for curr, amt in max_day1.items()}
    queue = deque(max_day1.keys())
    while queue:
        curr = queue.popleft()
        if curr in adj2:
            for neighbor, rate in adj2[curr]:
                new_amount = max_final[curr] * rate
                if neighbor not in max_final or new_amount > max_final[neighbor]:
                    max_final[neighbor] = new_amount
                    queue.append(neighbor)

    # 回傳所有可能結果中的最大值 (包含初始幣種本身)
    return max(max_final.values()) if max_final else 1.0
