        r = rates2[i]
        if u not in adj2: adj2[u] = []
        adj2[u].append((v, r))
        if v not in adj2: adj2[v] = []
        adj2[v].append((u, 1.0 / r))

    # Function to find max multiplier between any two currencies on a specific day
    def get_max_multipliers(adj, start_node):
        # Standard BFS/DFS for longest path in DAG (or simply all paths since no cycles)
        # Since constraints are small (n, m <= 10), we can use simple recursion with memoization
        memo = {}
        def dfs(curr):
            if curr in memo: return memo[curr]
            res = {curr: 1.0}
            if curr in adj:
                for neighbor, rate in adj[curr]:
                    sub_results = dfs(neighbor)
                    for node, multiplier in sub_results.items():
                        val = multiplier * rate
                        if node not in res or val > res[node]:
                            res[node] = val
            memo[curr] = res
            return res

        # However, because we need to handle the fact that paths can be complex 
        # and we want max amount, let's just use a simpler reachability/max path.
        # Given n is small, we find all possible reachable nodes from start_node.
        reachable = {start_node: 1.0}
        changed = True
        while changed:
            changed = False
            for u in list(reachable.keys()):
                if u in adj:
                    for v, r in adj[u]:
                        new_val = reachable[u] * r
                        if v not in reachable or new_val > reachable[v]:
                            reachable[v] = new_val
                            changed = True
        return reachable

    # Step 1: Find all possible amounts of any currency after Day 1
    day1_results = get_max_multipliers(adj1, initialCurrency)

