```python
from typing import List

def minOperations(nums: List[int]) -> int:
    n = len(nums)
    if n == 0: return 0
    if n == 1: return 0

    max_val = max(nums)
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    possible_values = []
    all_vals_set = set()
    for x in nums:
        opts = []
        if x == 1:
            opts.append((1, 0))
        else:
            p = spf[x]
            # Option 1: Keep the number as is (cost 0)
            opts.append((x, 0))
            # Option 2: Divide by greatest proper divisor (result is smallest prime factor p)
            # This operation is only useful if x > 1 and the result p < x.
            if p < x:
                opts.append((p, 1))
        opts.sort()
        possible_values.append(opts)
        for v, c in opts:
            all_vals_set.add(v)

    all_vals = sorted(list(all_vals_set))
    val_map = {v: i + 1 for i, v in enumerate(all_vals)}
    m = len(all_vals)
    bit = [float('inf')] * (m + 1)

    def update(idx, val):
        while idx <= m:
            if val < bit[idx]:
                bit[idx] = val
            else:
                break
            idx += idx & (-idx)

    def query(idx):
        res = float('inf')
        while idx > 0:
            if bit[idx] < res:
                res = bit[idx]
            idx -= idx & (-idx)
        return res

    # dp_prev will store (value, min_ops) for the current index i-1
    dp_prev = []
    for v, c in possible_values[0]:
        dp_prev.append((v, c))

    modified_indices = []
    # We need to initialize modified_indices for the first iteration of the loop (i=1)
    # which uses values from i=0.
    for v, c in dp_prev:
        modified_indices.append(val_map[v])

    for i in range(1, n):
        # Clear BIT from previous step results
        for idx in modified_indices:
            bit[idx] = float('inf')
        modified_indices = []

        # Populate BIT with dp_prev values (results of index i-1)
        for v, c in dp_prev:
            update(val_map[v], c)
            modified_indices.append(val_map[v])

        dp_curr = []
        for v, cost in possible_values[i]:
            best_prev = query(val_map[v])
            if best_prev != float('inf'):
                dp_curr.append((v, best_prev + cost))

        if not dp_curr: return -1
        dp_prev = dp_curr

    ans = min(c for v, c in dp_prev)
    return int(ans) if ans != float('inf') else -1
